// The only place the gatekeeper talks HTTP to PagerDuty's REST API. One request carries the bearer
// token, PagerDuty's versioned `Accept` header and, on writes, the `From` header naming the
// connected user; it has a timeout and a capped body read, never follows a redirect, and turns a
// non-2xx answer into a `PagerDutyApiError`.
//
// Calls go through typed clients whose paths, parameters and bodies come from PagerDuty's OpenAPI
// description (src/openapi/, generated by `pnpm generate:openapi`). Their replies keep the
// gatekeeper's own types instead (see `Replies`).

import {
  createOpenAPIClient, type Client, type OpenAPIClientOptions, type Operation, type Schema,
} from "@gadgets/gatekeeper-kit/http";
import { HttpError } from "@gadgets/gatekeeper-kit/http-errors";
import { readTextCapped } from "@gadgets/gatekeeper-kit/response-body";
import type { EscalationPoliciesApi } from "./openapi/escalationPolicies";
import type { IncidentsApi } from "./openapi/incidents";
import type { OnCallsApi } from "./openapi/onCalls";
import type { PrioritiesApi } from "./openapi/priorities";
import type { SchedulesApi } from "./openapi/schedules";
import type { SchedulesV3Api } from "./openapi/schedulesV3";
import type { ServicesApi } from "./openapi/services";
import type { TeamsApi } from "./openapi/teams";
import type { UsersApi } from "./openapi/users";
import { apiOrigin, type Region } from "./pagerduty-env";
import type {
  WireAlert, WireIncident, WireLogEntry, WireMember, WireNote, WireOnCall, WireOverride, WirePriority,
  WireRef, WireSchedule, WireService, WireShiftOverride, WireTeam, WireUser,
} from "./pagerduty-normalize";

const REQUEST_TIMEOUT_MS = 30_000;
/** A page of 100 incidents with their references is well under this. */
const MAX_RESPONSE_BYTES = 4 * 1024 * 1024;
/** PagerDuty's largest page. */
export const MAX_LIMIT = 100;
/** PagerDuty refuses a listing whose `offset + limit` exceeds this. */
const MAX_OFFSET = 10_000;
const ACCEPT = "application/vnd.pagerduty+json;version=2";

/** A listing's reply: its rows under `key`, and whether more follow. */
type Listing<K extends string, W> = { more?: boolean } & { [_ in K]: W[] };

/**
 * The replies the gatekeeper reads, by `<method> <path>`, as its own types in
 * pagerduty-normalize.ts declare them. PagerDuty's description leaves nearly every reply field
 * optional, every object's `id` included, which the converters cannot work with, so a reply is
 * trusted to have the fields they read, as it was before the description typed the requests. A
 * reply this table leaves out is `unknown`.
 */
type Replies = {
  "get /users/me": { user: WireUser };
  "get /users/{id}": { user: WireUser };
  "get /users": Listing<"users", WireUser>;
  "get /priorities": Listing<"priorities", WirePriority>;
  "get /teams": Listing<"teams", WireTeam>;
  "get /teams/{id}": { team: WireTeam };
  "get /teams/{id}/members": Listing<"members", WireMember>;
  "get /services": Listing<"services", WireService>;
  "get /services/{id}": { service: WireService };
  "get /escalation_policies": Listing<"escalation_policies", WireRef>;
  "get /escalation_policies/{id}": { escalation_policy: WireRef };
  "get /oncalls": Listing<"oncalls", WireOnCall>;
  "get /schedules": Listing<"schedules", WireSchedule>;
  "get /schedules/{id}": { schedule: WireSchedule };
  "get /schedules/{id}/overrides": { overrides: WireOverride[] };
  "post /schedules/{id}/overrides": { status: number; errors?: string[]; override?: WireOverride }[];
  "get /v3/schedules": Listing<"schedules", WireSchedule>;
  "get /v3/schedules/{id}": { schedule: WireSchedule };
  "get /v3/schedules/{id}/overrides": { overrides: WireShiftOverride[] };
  "get /incidents": Listing<"incidents", WireIncident>;
  "post /incidents": { incident: WireIncident };
  "get /incidents/{id}": { incident: WireIncident };
  "get /incidents/{id}/alerts": Listing<"alerts", WireAlert>;
  "get /incidents/{id}/log_entries": Listing<"log_entries", WireLogEntry>;
  "get /incidents/{id}/notes": { notes: WireNote[] };
};

/** Operation `O`, sent with method `M`, replying as `Replies` says. */
type WithReply<O, M extends string> = O extends Operation
  ? Omit<O, "response"> & {
    readonly response: `${M} ${O["path"]}` extends keyof Replies ? Replies[`${M} ${O["path"]}`] : unknown;
  }
  : never;

/** Schema `S`, its replies as `Replies` says. */
type Replying<S extends Schema> = {
  readonly [M in keyof S]: S[M] extends readonly (infer O)[] ? readonly WithReply<O, M & string>[] : S[M];
};

/** PagerDuty's REST API, one typed client per group of its description. */
export type Rest = {
  escalationPolicies: Client<Replying<EscalationPoliciesApi>>;
  incidents: Client<Replying<IncidentsApi>>;
  onCalls: Client<Replying<OnCallsApi>>;
  priorities: Client<Replying<PrioritiesApi>>;
  schedules: Client<Replying<SchedulesApi>>;
  schedulesV3: Client<Replying<SchedulesV3Api>>;
  services: Client<Replying<ServicesApi>>;
  teams: Client<Replying<TeamsApi>>;
  users: Client<Replying<UsersApi>>;
};

/** The query of the GET operation at `path` in a schema from src/openapi/. */
export type QueryOf<S extends Schema, P extends string> =
  NonNullable<Extract<NonNullable<S["get"]>[number], { readonly path: P }>["query"]>;

/** The body of the operation sent with method `M` at `path` in a schema from src/openapi/. */
export type BodyOf<S extends Schema, M extends keyof S, P extends string> =
  NonNullable<S[M]> extends readonly (infer O)[]
    ? Extract<O, { readonly path: P }> extends { readonly body?: infer B } ? NonNullable<B> : never
    : never;

/** Where a listing page starts and how many rows it holds, as PagerDuty's query takes them. */
export type PageQuery = { offset: number; limit: number };

/** PagerDuty's refusal of a request. */
export class PagerDutyApiError extends HttpError {
  constructor(status: number, message: string) {
    super(status, message);
    this.name = "PagerDutyApiError";
  }
}

/** Whether PagerDuty refused the credentials themselves (an expired or revoked token). */
export function isAuthError(error: unknown): boolean {
  return error instanceof PagerDutyApiError && error.status === 401;
}

/** Whether PagerDuty said the user can't see what was asked for: a definite "no access". */
export function isDenial(error: unknown): boolean {
  return error instanceof PagerDutyApiError && (error.status === 403 || error.status === 404);
}

/**
 * Whether PagerDuty refused the request itself, so repeating it would only be refused again: any
 * 4xx but a credential rejection or a rate limit.
 */
export function isRefusal(error: unknown): error is PagerDutyApiError {
  return error instanceof PagerDutyApiError && error.status < 500 && error.status !== 401 && error.status !== 429;
}

/** One page of a classic offset listing. */
export type Page<T> = { items: T[]; more: boolean };

/** One listing a walk draws on: its rows from `offset`, at most `limit`. */
export type OffsetSource<T> = (api: PagerDutyApi, offset: number, limit: number) => Promise<Page<T>>;

/** A reply holding a listing's rows. */
type ListingReply = { more?: boolean };

/** The listing `read` fetches a page of, whose rows `rows` picks out of the reply, each converted. */
export const listing = <B extends ListingReply, W, T>(
  read: (api: PagerDutyApi, page: PageQuery) => Promise<B>, rows: (reply: B) => readonly W[],
  convert: (wire: W) => T,
): OffsetSource<T> =>
  async (api, offset, limit) => {
    const page = await pageOf(read(api, { offset, limit }), rows);
    return { ...page, items: page.items.map(convert) };
  };

/** The rows `rows` picks out of a listing reply, and whether more follow. */
async function pageOf<B extends ListingReply, W>(reply: Promise<B>, rows: (reply: B) => readonly W[]): Promise<Page<W>> {
  const body = await reply;
  const items = rows(body);
  if (!Array.isArray(items)) throw new Error("PagerDuty's listing was malformed.");
  return { items: [...items], more: body.more === true };
}

/** The filters a schedule listing takes, of either generation. */
export type ScheduleFilters = QueryOf<SchedulesApi, "/schedules"> & QueryOf<SchedulesV3Api, "/v3/schedules">;

/** Schedules: layer-based ones, then shift-based ones, which PagerDuty lists apart. */
export const scheduleListings = <T>(query: ScheduleFilters, convert: (wire: WireSchedule, shiftBased: boolean) => T):
  OffsetSource<T>[] => [
  listing((api, page) => api.rest.schedules.get("/schedules", { query: { ...query, ...page } }),
    reply => reply.schedules, wire => convert(wire, false)),
  listing((api, page) => api.rest.schedulesV3.get("/v3/schedules", { query: { ...query, ...page } }),
    reply => reply.schedules, wire => convert(wire, true)),
];

/**
 * Up to `limit` rows of `sources`, walked in turn from `token`, `<source>:<offset>`, where the last
 * page stopped. The next source starts once one runs out, or reaches PagerDuty's offset cap.
 * @throws Error for a token no walk of `sources` hands out.
 */
export async function chainedPage<T>(api: PagerDutyApi, sources: readonly OffsetSource<T>[], token: string | undefined,
                                     limit: number): Promise<{ items: T[]; nextToken?: string }> {
  let [index, offset] = token === undefined ? [0, 0] : token.split(":").map(Number) as [number, number];
  if (!Number.isSafeInteger(index) || !Number.isSafeInteger(offset) || index < 0 || index >= sources.length
    || offset < 0 || offset >= MAX_OFFSET) {
    throw new Error("That page has expired. Try again.");
  }
  const items: T[] = [];
  while (index < sources.length && items.length < limit) {
    const page = await sources[index]!(api, offset, Math.min(MAX_LIMIT, limit - items.length, MAX_OFFSET - offset));
    items.push(...page.items);
    offset += page.items.length;
    if (!page.more || page.items.length === 0 || offset >= MAX_OFFSET) [index, offset] = [index + 1, 0];
  }
  return { items, ...(index < sources.length ? { nextToken: `${index}:${offset}` } : {}) };
}

type ErrorBody = { error?: { message?: unknown; errors?: unknown } };

/** A display-safe error for a non-2xx answer. */
function errorFor(response: Response, text: string): PagerDutyApiError {
  if (response.status === 429) {
    const reset = Number(response.headers.get("ratelimit-reset"));
    const wait = Number.isFinite(reset) && reset > 0 ? `in ${Math.ceil(reset)} seconds` : "shortly";
    return new PagerDutyApiError(429, `PagerDuty is rate limiting this connection; try again ${wait}.`);
  }
  let body: ErrorBody = {};
  try {
    body = JSON.parse(text) as ErrorBody;
  } catch {
    // Not JSON: the status alone describes it.
  }
  const { message, errors } = body.error ?? {};
  const details = [
    typeof message === "string" ? message : undefined,
    ...(Array.isArray(errors) ? errors.filter(error => typeof error === "string") : []),
  ].filter(Boolean).join("; ").slice(0, 500);
  return new PagerDutyApiError(response.status, `PagerDuty answered HTTP ${response.status}${details ? `: ${details}` : "."}`);
}

/** The kinds of object `PagerDutyApi.object` reads. */
export type ObjectKind = "team" | "service" | "incident" | "escalation_policy" | "schedule";

/** A REST client for one account, acting as one user. */
export class PagerDutyApi {
  readonly #token: string;
  readonly #from?: string;
  /** PagerDuty's REST operations, each sent as `#exchange` sends every request. */
  readonly rest: Rest;

  /**
   * @param token The user's OAuth access token.
   * @param region The account's region, which picks the REST host.
   * @param from The user's email, which PagerDuty requires on writes.
   */
  constructor(token: string, region: Region, from?: string) {
    this.#token = token;
    this.#from = from;
    const options: OpenAPIClientOptions = {
      baseUrl: apiOrigin(region),
      fetch: request => this.#exchange(request),
      maxResponseBytes: MAX_RESPONSE_BYTES,
    };
    this.rest = {
      escalationPolicies: createOpenAPIClient<Replying<EscalationPoliciesApi>>(options),
      incidents: createOpenAPIClient<Replying<IncidentsApi>>(options),
      onCalls: createOpenAPIClient<Replying<OnCallsApi>>(options),
      priorities: createOpenAPIClient<Replying<PrioritiesApi>>(options),
      schedules: createOpenAPIClient<Replying<SchedulesApi>>(options),
      schedulesV3: createOpenAPIClient<Replying<SchedulesV3Api>>(options),
      services: createOpenAPIClient<Replying<ServicesApi>>(options),
      teams: createOpenAPIClient<Replying<TeamsApi>>(options),
      users: createOpenAPIClient<Replying<UsersApi>>(options),
    };
  }

  /**
   * Schedule `id`, read without parameters from the API of its generation, and whether it is
   * shift-based. v3 is asked first, as PagerDuty recommends: it answers 400 for a layer-based
   * schedule, which v2 then serves.
   */
  async schedule(id: string): Promise<{ schedule: WireSchedule; shiftBased: boolean }> {
    try {
      const { schedule } = await this.rest.schedulesV3.get("/v3/schedules/{id}", { path: { id } });
      return { schedule, shiftBased: true };
    } catch (error) {
      if (!(error instanceof PagerDutyApiError && error.status === 400)) throw error;
    }
    const { schedule } = await this.rest.schedules.get("/schedules/{id}", { path: { id } });
    return { schedule, shiftBased: false };
  }

  /** The object `id` of `kind`; a schedule of either generation. */
  async object(kind: ObjectKind, id: string): Promise<WireRef> {
    switch (kind) {
      case "team": return (await this.rest.teams.get("/teams/{id}", { path: { id } })).team;
      case "service": return (await this.rest.services.get("/services/{id}", { path: { id } })).service;
      case "incident": return (await this.rest.incidents.get("/incidents/{id}", { path: { id } })).incident;
      case "escalation_policy":
        return (await this.rest.escalationPolicies.get("/escalation_policies/{id}", { path: { id } })).escalation_policy;
      case "schedule": return (await this.schedule(id)).schedule;
    }
  }

  /**
   * Every row of the listing `read` fetches pages of, which `rows` picks out of each reply, up to
   * `max` and PagerDuty's offset cap.
   */
  async all<B extends ListingReply, W>(read: (page: PageQuery) => Promise<B>, rows: (reply: B) => readonly W[],
                                       max = MAX_OFFSET): Promise<W[]> {
    return (await chainedPage(this, [(_, offset, limit) => pageOf(read({ offset, limit }), rows)], undefined, max)).items;
  }

  /**
   * Sends a request the typed clients built, with the token, PagerDuty's `Accept` header and, on a
   * write, `From`. A 2xx answer is returned for the client to read; any other fails.
   */
  async #exchange(request: Request): Promise<Response> {
    const headers = new Headers(request.headers);
    headers.set("Authorization", `Bearer ${this.#token}`);
    headers.set("Accept", ACCEPT);
    if (request.method !== "GET") {
      if (!this.#from) throw new Error("A PagerDuty write needs the connected user's email.");
      headers.set("From", this.#from);
    }
    let response: Response;
    try {
      response = await fetch(request.url, {
        method: request.method,
        headers,
        body: request.body === null ? undefined : await request.text(),
        redirect: "manual",
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
    } catch (error) {
      const timedOut = error instanceof DOMException && error.name === "TimeoutError";
      throw new Error(timedOut ? "PagerDuty did not answer in time; please try again." : "Could not reach PagerDuty; please try again.",
        { cause: error });
    }
    if (response.status >= 300 && response.status < 400) {
      await response.body?.cancel();
      throw new PagerDutyApiError(response.status, "PagerDuty answered with an unexpected redirect.");
    }
    if (response.ok) return response;
    let text: string;
    try {
      text = await readTextCapped(response, MAX_RESPONSE_BYTES);
    } catch (error) {
      throw new Error("PagerDuty's response could not be read; please try again.", { cause: error });
    }
    throw errorFor(response, text);
  }
}
